query (
  $startTime: DateTime!,
  $endTime: DateTime!
){
  workcenterHistory(
    where:{ 
      _or:[
        {
          _and:[
            { occurAt:{_gte: $startTime} }
            { occurAt:{_lt: $endTime} }
          ]
        },
        {
          _and:[
            { endAt:{_gte: $startTime} }
            { endAt:{_lt: $endTime} }
          ]
        },
        { 
        	endAt: { _isNull: true },
          occurAt: {_lt: $endTime}
        }
      ]
    }
    first: null
	) {
    edges {
      node {
        id
        occurAt
        endAt
        duration
        creditedAt
        transactionTypeId
        workcenterId

          mode{
            id
            name
            modeType{
              production
            }            
          }
          event{
            eventType{
              unplannedDowntime
              plannedDowntime
              running
            }
          }

        shift{
          id
          name
          startHour
          startMinute
          endHour
          endMinute
        }
        productionRun{
          id
          idealAggregate
          standardAggregate
          startAt
          endAt
        }
      }
    }
  }

  workcenter(first: null){
      edges{
          node{ 
            id  
            name
          }
      }
  }

  productionSetup(first: null){
  	edges{
      node{
        id
        workcenterId
        workcenter{
          shiftGroup{
            shifts{
              edges{
                node{
                  id
                  name
                  startHour
                  startMinute
                  endHour
                  endMinute
                  creditAtStart

                  monday
                  tuesday
                  wednesday
                  thursday
                  friday
                  saturday
                  sunday
                }
              }
            }
          }
        }
        productionRun{
          idealAggregate
          standardAggregate
        }

      }
    }
	}

  productionSetupOutput(first:null){
    edges{
      node{
        productNumberRevision
        operationCode
        operationNumber
        productName
        productRevision
        workOrderNumber
        outputId
        counterInput
        cycleTime
        idealRate
        setupRate
        standardQuantity
        standardRate
        unitPerCycle

      }
    }
  }

  setting(where:{
    id: {_eq: "TimeZone"}
  }) {
    edges {
      node {
        id
        defaultValue
      }
    }
  }
}

{
  oeeConfiguration{
    edges{
      node{
        id
        oeeTimeFrameId
        lastRanAt
        oeeDimensions{
          total
          edges{
            node{
              oeeDimension{
                field
              }
            }
          }
        }
      }
    }
  }
}

