  $start: DateTime!,
  $end: DateTime!,
){
  oee(
    first:null
    where:{
			_and:[
        { creditedAt:{_gte: $start} },
        { creditedAt:{_lte: $end}}
      ]
  	}){
    total
    edges{
      node{
        id
        workOrderCode
        workOrderNumber
        shiftId
        productNoRevision
        workcenterId

        oee

        availability
        availabilityWeight
        totalTime
        productionTime
        plannedDowntime
        unplannedDowntime

        performance
        performanceWeight
        idealRate
        totalQuantity
        totalScrapQuantity
        totalProductionQuantity

        quality
        qualityWeight

        creditedAt
      }
    }
  }
}

