    ?,
    function($oees){(

      $oees := $oees~>|$| 
        {
          "availabilityWeighted": availability * (availabilityWeight?availabilityWeight:0),
          "performanceWeighted": performance * productionTime,
          "qualityWeighted": quality * totalQuantity
        }
       |;       

      /*Calculate Availability*/
      $plannedProductionTime := $sum($oees.productionTime);
      $unplannedDownTime := $sum($oees.unplannedDowntime);

