        $startInTimeZone := $momentTz($start, undefined, $timeZone);
        $endInTimeZone := $momentTz($end, undefined, $timeZone);
        $dayDiff := $endInTimeZone.date() - $startInTimeZone.date();

        /*If the range spans more then a single day then we need to condsider that the 1D collision dection wont work.
          Break this into once per day per shift to decide if we should include a shift more then once.
        */
        [0..$dayDiff].(
          /*if this is the first day of the range we should use the start time otherwise we can just use the start of the day*/ 
          $start := $=0? $dateToInt($startInTimeZone.hour(), $startInTimeZone.minute()): 0;
          /*Same logic as the start time just for the end of the day*/
          $end := $=$dayDiff? $dateToInt($endInTimeZone.hour(), $endInTimeZone.minute()): 2359;

          $shiftStart := $dateToInt($v.startHour, $v.startMinute);
          $shiftEnd := $dateToInt($v.endHour, $v.endMinute);

          $cantUse$WithMomentInALoopForSomeReason := $;
          $dayOfWeek := $startInTimeZone.clone().add($cantUse$WithMomentInALoopForSomeReason, "day").format("dddd")~>$lowercase;

          /* Its possible we might hit a shift twice if it spans more then one day here we adjust the day that it counts towards based on the creditAt */
          $result := ($shiftStart < $shiftEnd and $end > $shiftStart and $shiftEnd > $start and $lookup($v, $dayOfWeek))? 
            {"hit": true, "day": $} :
          ($shiftStart > $shiftEnd and ($end > $shiftStart or $start >= $shiftStart ) and $lookup($v, $dayOfWeek) )?
            {"hit": true, "day": $v.creditAtStart? $ : $+1} :
          ($shiftStart > $shiftEnd and ($end < $shiftEnd or $start < $shiftEnd ) and $lookup($v, $dayOfWeek) )?
            {"hit": true, "day": $v.creditAtStart? $-1 : $} :
            {"hit": false};


           $result.hit? $merge([$v, {"day": $result.day, "start": $start, "end": $end, "ss": $shiftStart, "se": $shiftEnd, "hit": $result.hit}]) 
        );

      )}
  )
    ~>$flatten
    ~>$uniqBy(?, $pick(?, ["id", "day"])~>$values~>$join(?, "::") )
    ~>$filter($isNil~>$not)^(day, startHour, startMinute)
     ~> | $ | { "creditAt": $findCreditAt($) } | 

  )};
  $fitModeToRange := function($startBound, $endBound, $mode){(

    $modeStart := $coalesce([ $mode.occurAt , $startBound])~>$moment(?) ;
    $modeEnd := $coalesce([ $mode.endAt, $endBound])~>$moment(?);

    $endBoundObj := $moment($endBound);
    $startBoundObj := $moment($startBound);

    $start := $modeStart.isAfter($startBound)? $modeStart : $startBoundObj;
    $end := $modeEnd.isBefore($endBound)? $modeEnd : $endBoundObj;

    $isNilOrEmpty($mode.occurAt) and $isNilOrEmpty($mode.endAt)? 
      $throw("Mode has no occurAt or endAt", $mode) :
      $merge([
        $mode,
        {"duration": $end.diff($start, "second") , "occurAt": $start.format(), "endAt": $end.format(), "originalTimes":{"occurAt": $modeStart, "endAt": $endAt}}
      ])

