      $endMinute := endMinute;

      $shiftStart := $startHour + ($startMinute / 60);
      $shiftEnd := $endHour + ($endMinute / 60);

      $range := ((($shiftEnd + 24) - $shiftStart) % 24);
      $isModeStartInShift := ((($modeStart + 24) - $shiftStart) % 24) < $range;
      $isModeEndInShift := ((($modeEnd + 24) - $shiftStart) % 24) < $range;

