        $mode.occurAt : 
        ($momentTz($state.context.startTime, undefined, $timeZone)).set({"hour": $startHour, "minute": $startMinute}).utc().format();

      $newEndAt := $isModeEndInShift?
        $mode.endAt : 
        $momentTz($state.context.startTime, undefined, $timeZone).set({"hour": $endHour, "minute": $endMinute}).utc().format();

      $merge([
        $mode,
        {"occurAt": $newOccurAt, "endAt": $newEndAt},
        {"currentShift": $}


      ])

    )
  )};
  $calculateSeconds := function($mode){(
    $start := $moment($mode.occurAt);
