      $hourStart := $hourStartDate.hour() + ($hourStartDate.minute() / 60);
      $hourEnd := $hourEndDate.hour() + ($hourEndDate.minute() / 60);

      $range := ((($hourEnd + 24) - $hourStart) % 24);

